const state={types:[],entities:[],relationships:[]};
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
async function api(url,options){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options});const b=r.status===204?{}:await r.json();if(!r.ok)throw Error(b.error||'Request failed');return b}
const kindLabel=k=>k==='entity'?'Entities':k==='relationship'?'Relationships':k==='view'?'Views':'Presentations';
const typeCard=t=>`<div class="card type-card"><span class="chip">${esc(t.kind)}</span><h3>${esc(t.name)}</h3><p>${esc(t.description)||'No description yet.'}</p><small class="muted">${(t.schema?.properties||[]).length} properties</small><div><button class="button secondary small" onclick="showTypeFormById('${t.id}')">Configure</button>${['view','presentation'].includes(t.kind)?` <button class="button secondary small" onclick="previewDefinition('${t.id}')">Open</button>`:''}</div></div>`;
function showTypeFormById(id){const t=state.types.find(x=>x.id===id);if(t)showTypeForm(t.kind,t)}
function previewDefinition(id){const t=state.types.find(x=>x.id===id);if(!t)return;const config=t.schema?.config||{};formShell(t.name,`<div class="projection-preview"><span class="chip">${esc(t.kind)} projection</span><h2>${esc(t.description)||'No description'}</h2><p>Source: <strong>${esc(config.source_kind||'configured view set')}</strong></p><p>Layout: <strong>${esc(config.layout||'composed')}</strong></p><p>${config.filter?`Filter: ${esc(config.filter)}`:`No filter configured.`}</p>${config.view_ids?.length?`<p>Ordered views: ${config.view_ids.map(esc).join(' → ')}</p>`:''}</div>`)}
function renderOverview(){$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">COMPOSABLE META-MODEL WORKSPACE · ${esc(state.version||'')}</div><h1>Give your domain a shape.</h1><p>Define forms first, then instantiate the people, places, objects, and events your work needs.</p></div><div><button class="button" onclick="showTypeForm('entity')">+ Define an entity type</button><button class="button secondary small" onclick="resetWorkspace()">Reset test workspace</button></div></div><div class="grid"><div class="stat"><div class="stat-label">Entity types</div><div class="stat-value">${state.types.filter(t=>t.kind==='entity').length}</div></div><div class="stat"><div class="stat-label">Entity records</div><div class="stat-value">${state.entities.length}</div></div><div class="stat"><div class="stat-label">Relationships</div><div class="stat-value">${state.relationships.length}</div></div><div class="stat"><div class="stat-label">View definitions</div><div class="stat-value">${state.types.filter(t=>['view','presentation'].includes(t.kind)).length}</div></div></div><div class="section-title"><h2>Definitions</h2><span class="chip">Metadata-driven</span></div><div class="card-grid">${state.types.map(typeCard).join('')}</div>`}
async function resetWorkspace(){if(!confirm('Reset this non-production workspace? All records and custom definitions will be removed.'))return;try{await api('/api/reset',{method:'POST'});await load();toast('Workspace reset to core definitions')}catch(err){toast(err.message)}}
function showSection(s){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.section===s));if(s==='overview')return renderOverview();if(s==='entities')return renderEntities();if(s==='relationships')return renderRelationships();renderDefinitions(s)}
function renderEntities(){$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">ENTITY RECORDS</div><h1>Entities</h1><p>Create instances from typed definitions. Existing records can be edited and inspected field by field.</p></div><button class="button" onclick="showEntityForm()">+ New entity</button></div><div class="card">${state.entities.length?`<table class="table"><thead><tr><th>Name</th><th>Type</th><th>Properties</th><th></th></tr></thead><tbody>${state.entities.map(e=>`<tr><td>${esc(e.name)}</td><td><span class="chip">${esc(e.type_name)}</span></td><td>${renderDataSummary(e.data)}</td><td><button class="button secondary small" onclick="showEntityForm('${e.id}')">Edit</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No entity records yet. Define a type, then create your first instance.</div>'}</div>`}
function renderDataSummary(data){return Object.entries(data||{}).map(([k,v])=>`<div><strong>${esc(k)}</strong>: ${esc(Array.isArray(v)?v.join(', '):typeof v==='object'?JSON.stringify(v):v)}</div>`).join('')||'<span class="muted">No properties</span>'}
function renderRelationships(){$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">RELATIONSHIP RECORDS</div><h1>Relationships</h1><p>Connections are typed facts with constrained endpoints and their own properties.</p></div><button class="button" onclick="showRelationshipForm()">+ New relationship</button></div><div class="card">${state.relationships.length?`<table class="table"><thead><tr><th>Type</th><th>From</th><th>To</th><th>Properties</th></tr></thead><tbody>${state.relationships.map(r=>`<tr><td><span class="chip">${esc(r.type_name)}</span></td><td>${esc(r.from_name)}</td><td>${esc(r.to_name)}</td><td>${renderDataSummary(r.data)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No relationships yet. Define a type and create a connection.</div>'}</div>`}
function renderDefinitions(s){const kind=s==='views'?'view':s==='presentations'?'presentation':s.slice(0,-1);const items=state.types.filter(t=>t.kind===kind);$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">${kind.toUpperCase()} DEFINITIONS</div><h1>${kind[0].toUpperCase()+kind.slice(1)}s</h1><p>Definitions are stored as metadata and can be expanded as the model evolves.</p></div><button class="button" onclick="showTypeForm('${kind}')">+ Define ${kind}</button></div><div class="card-grid">${items.map(typeCard).join('')||'<div class="empty">No definitions yet.</div>'}</div>`}
function formShell(title,body){$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">MODEL BUILDER</div><h1>${title}</h1></div><button class="button secondary" onclick="renderOverview()">Cancel</button></div><div class="card form-card">${body}</div>`}
function propertyRow(p={},i=0){const targets=state.types.filter(t=>t.kind==='entity');return `<div class="property-row" data-index="${i}"><div class="form-row"><div class="field"><label>Property name</label><input name="property_name" value="${esc(p.name)}" placeholder="e.g. species"></div><div class="field"><label>Label</label><input name="property_label" value="${esc(p.label||p.name)}" placeholder="Display label"></div></div><div class="form-row"><div class="field"><label>Value kind</label><select name="property_kind"><option value="text" ${p.value_kind==='text'?'selected':''}>Text</option><option value="long_text" ${p.value_kind==='long_text'?'selected':''}>Long text</option><option value="number" ${p.value_kind==='number'?'selected':''}>Number</option><option value="boolean" ${p.value_kind==='boolean'?'selected':''}>Boolean</option><option value="date" ${p.value_kind==='date'?'selected':''}>Date</option><option value="json" ${p.value_kind==='json'?'selected':''}>JSON</option><option value="entity_reference" ${p.value_kind==='entity_reference'?'selected':''}>Entity reference</option></select></div><div class="field"><label>Cardinality</label><select name="property_cardinality"><option value="one" ${p.cardinality!=='many'?'selected':''}>One</option><option value="many" ${p.cardinality==='many'?'selected':''}>Many (list)</option></select></div></div><div class="field"><label>Allowed entity types for references</label><select name="property_targets" multiple>${targets.map(t=>`<option ${p.target_kinds?.includes(t.name)?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="form-row"><div class="field"><label>Minimum values</label><input name="property_min" type="number" min="0" value="${esc(p.min??'')}"></div><div class="field"><label>Maximum values</label><input name="property_max" type="number" min="0" value="${esc(p.max??'')}"></div></div><div class="form-row"><div class="field"><label><input type="checkbox" name="property_required" ${p.required?'checked':''}> Required</label></div><div class="field"><label><input type="checkbox" name="property_allow_duplicates" ${p.allow_duplicates?'checked':''}> Allow duplicate reference IDs</label></div></div><div class="field"><label>Description</label><input name="property_description" value="${esc(p.description)}" placeholder="What does it mean?"></div><button type="button" class="button secondary small" onclick="this.closest('.property-row').remove()">Remove property</button></div>`}
function collectProperties(){return [...document.querySelectorAll('.property-row')].map(row=>{const g=n=>row.querySelector(`[name="${n}"]`);return {name:g('property_name').value,label:g('property_label').value,value_kind:g('property_kind').value,cardinality:g('property_cardinality').value,required:g('property_required').checked,allow_duplicates:g('property_allow_duplicates').checked,description:g('property_description').value,target_kinds:[...g('property_targets').selectedOptions].map(x=>x.value),min:g('property_min').value===''?null:Number(g('property_min').value),max:g('property_max').value===''?null:Number(g('property_max').value)}}).filter(p=>p.name||p.label)}
function showTypeForm(kind='entity',existing){const t=existing||null;const entityKinds=state.types.filter(x=>x.kind==='entity').map(x=>x.name);const config=t?.schema?.config||{};const configFields=kind==='view'?`<div class="section-title"><h2>View projection</h2></div><div class="form-row"><div class="field"><label>Source kind</label><select name="source_kind"><option value="entity" ${config.source_kind!=='relationship'?'selected':''}>Entity</option><option value="relationship" ${config.source_kind==='relationship'?'selected':''}>Relationship</option></select></div><div class="field"><label>Layout</label><select name="layout"><option ${config.layout==='list'?'selected':''}>list</option><option ${config.layout==='table'?'selected':''}>table</option><option ${config.layout==='graph'?'selected':''}>graph</option><option ${config.layout==='timeline'?'selected':''}>timeline</option></select></div></div><div class="field"><label>Filter expression</label><input name="filter" value="${esc(config.filter)}" placeholder="Optional filter"></div>`:kind==='presentation'?`<div class="section-title"><h2>Presentation composition</h2></div><div class="field"><label>Ordered view IDs (one per line)</label><textarea name="view_ids">${esc((config.view_ids||[]).join('\n'))}</textarea></div><div class="field"><label>Active view ID</label><input name="active_view_id" value="${esc(config.active_view_id)}"></div>`:'';formShell(`${t?'Edit':'Define'} a ${kind} type`,`<form id="type-form"><div class="form-row"><div class="field"><label>Kind</label><select name="kind" ${t?'disabled':''}>${['entity','relationship','view','presentation'].map(k=>`<option ${k===kind?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label>Name</label><input name="name" value="${esc(t?.name)}" placeholder="e.g. Character" required></div></div><div class="field"><label>Description</label><textarea name="description" placeholder="What does this definition represent?">${esc(t?.description)}</textarea></div>${kind==='relationship'?`<div class="form-row"><div class="field"><label>Allowed source entity types</label><select name="source_kinds" multiple>${entityKinds.map(k=>`<option ${t?.schema?.source_kinds?.includes(k)?'selected':''}>${esc(k)}</option>`).join('')}</select></div><div class="field"><label>Allowed target entity types</label><select name="target_kinds" multiple>${entityKinds.map(k=>`<option ${t?.schema?.target_kinds?.includes(k)?'selected':''}>${esc(k)}</option>`).join('')}</select></div></div><div class="field"><label>Inverse label (optional)</label><input name="inverse_label" value="${esc(t?.schema?.inverse_label)}" placeholder="e.g. is owned by"></div>`:''}${configFields}<div class="section-title"><h2>Properties</h2><button type="button" class="button secondary small" id="add-property">+ Add property</button></div><div id="properties">${(t?.schema?.properties||[]).map(propertyRow).join('')}</div><button class="button">Save definition</button></form>`);document.querySelector('#add-property').onclick=()=>document.querySelector('#properties').insertAdjacentHTML('beforeend',propertyRow({},document.querySelectorAll('.property-row').length));document.querySelector('#type-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body={kind,name:f.get('name'),description:f.get('description'),schema:{properties:collectProperties(),source_kinds:[...e.target.querySelector('[name="source_kinds"]')?.selectedOptions||[]].map(x=>x.value),target_kinds:[...e.target.querySelector('[name="target_kinds"]')?.selectedOptions||[]].map(x=>x.value),inverse_label:f.get('inverse_label')||'',config:{source_kind:f.get('source_kind')||'',layout:f.get('layout')||'',filter:f.get('filter')||'',view_ids:(f.get('view_ids')||'').split('\n').map(x=>x.trim()).filter(Boolean),active_view_id:f.get('active_view_id')||''}}};try{await api(t?`/api/types/${t.id}`:'/api/types',{method:t?'PUT':'POST',body:JSON.stringify(body)});await load();showSection(kindLabel(kind).toLowerCase());toast('Definition saved')}catch(err){toast(err.message)}}}
function showEntityForm(id){
  const existing=id&&state.entities.find(e=>e.id===id),types=state.types.filter(t=>t.kind==='entity'),initialType=existing?types.find(t=>t.id===existing.type_id||t.name===existing.type_name):types[0];
  if(!initialType)return showTypeForm('entity');
  const drafts={};
  if(existing)drafts[initialType.id]={...(existing.data||{})};
  formShell(`${existing?'Edit':'Create'} an entity`, `<form id="entity-form"><div class="form-row"><div class="field"><label>Entity type</label><select name="typeId" ${existing?'disabled':''}>${types.map(t=>`<option value="${t.id}" ${t.id===initialType.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><small class="muted">Changing type updates the fields immediately. Draft values are retained for each type until you save or cancel.</small></div><div class="field"><label>Name</label><input name="name" value="${esc(existing?.name)}" required></div></div><div id="dynamic-fields"></div><div class="field legacy-field"><label>Untyped JSON (optional legacy data)</label><textarea name="legacy">${esc(JSON.stringify(existing?.data||{},null,2))}</textarea><small class="muted">Legacy keys remain available and are preserved when typed fields are saved.</small></div><button class="button">${existing?'Save changes':'Create entity'}</button></form>`);
  const form=document.querySelector('#entity-form'),selector=form.querySelector('[name="typeId"]'),fields=form.querySelector('#dynamic-fields');
  const renderSelectedType=(capture=true)=>{const type=types.find(t=>t.id===selector.value)||types[0],props=type.schema?.properties||[],draft=drafts[type.id]||{};if(capture&&fields.innerHTML)drafts[type.id]=readFields(props,form);fields.innerHTML=props.map(p=>fieldFor(p,draft[p.name])).join('');};
  selector.onchange=()=>{const current=types.find(t=>t.id===selector.value);if(current)renderSelectedType();};
  renderSelectedType(false);
  form.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),type=types.find(t=>t.id===selector.value)||initialType,props=type.schema?.properties||[],data=readFields(props,e.target);try{const legacy=JSON.parse(f.get('legacy')||'{}');Object.assign(legacy,data);await api(existing?`/api/entities/${existing.id}`:'/api/entities',{method:existing?'PUT':'POST',body:JSON.stringify({typeId:type.id,name:f.get('name'),data:legacy})});await load();showSection('entities');toast(existing?'Entity updated':'Entity created')}catch(err){toast(err.message)}}
}
function referenceOptions(p,value=''){return `<option value="">— None selected —</option>${state.entities.filter(e=>!p.target_kinds?.length||p.target_kinds.includes(e.type_name)).map(e=>`<option value="${e.id}" ${e.id===value?'selected':''}>${esc(e.name)} · ${esc(e.type_name)}</option>`).join('')}`}
function referenceInput(p,value=''){return `<div class="reference-picker"><input class="reference-search" type="search" placeholder="Search allowed entities" oninput="filterReferenceOptions(this)"><select name="prop_${esc(p.name)}">${referenceOptions(p,value)}</select></div>`}
function fieldFor(p,value){const vals=p.cardinality==='many'?(Array.isArray(value)?value:[]):[value];const input=(v='')=>p.value_kind==='entity_reference'?referenceInput(p,v):p.value_kind==='long_text'?`<textarea name="prop_${esc(p.name)}">${esc(v)}</textarea>`:`<input name="prop_${esc(p.name)}" type="${p.value_kind==='number'?'number':p.value_kind==='date'?'date':'text'}" value="${esc(v)}">`;const list=p.value_kind==='entity_reference'?vals:vals.length?vals:[''];return `<div class="field generated-field"><label>${esc(p.label||p.name)} ${p.required?'*':''}<small>${esc(p.description)}</small></label>${p.cardinality==='many'?`<div class="list-values" data-prop="${esc(p.name)}" data-targets="${esc((p.target_kinds||[]).join('|'))}">${list.map(v=>`<div class="list-value">${input(v)}<button type="button" class="button secondary small" onclick="moveListValue(this,-1)">↑</button><button type="button" class="button secondary small" onclick="moveListValue(this,1)">↓</button><button type="button" class="button secondary small" onclick="this.parentElement.remove()">−</button></div>`).join('')}<button type="button" class="button secondary small" onclick="${p.value_kind==='entity_reference'?`addReferenceValue(this,'${esc(p.name)}')`:`addListValue(this,'${esc(p.name)}','${p.value_kind}')`}">+ Add value</button></div>`:input(value??'')}</div>`}
function filterReferenceOptions(search){const query=search.value.toLowerCase();const select=search.parentElement.querySelector('select');[...select.options].forEach(option=>{option.hidden=Boolean(option.value)&&!option.textContent.toLowerCase().includes(query);});}
function addReferenceValue(button,name){const list=button.parentElement,row=list.querySelector('.list-value');const template=row?row.cloneNode(true):document.createElement('div');if(!row){template.className='list-value';template.innerHTML=referenceInput({name,target_kinds:list.dataset.targets?list.dataset.targets.split('|'):[]});template.insertAdjacentHTML('beforeend','<button type="button" class="button secondary small" onclick="moveListValue(this,-1)">↑</button><button type="button" class="button secondary small" onclick="moveListValue(this,1)">↓</button><button type="button" class="button secondary small" onclick="this.parentElement.remove()">−</button>');}template.querySelectorAll('input,select').forEach(x=>x.value='');button.parentElement.insertBefore(template,button)}
function addListValue(button,name,kind){const row=button.parentElement.querySelector('.list-value');if(!row)return;const clone=row.cloneNode(true);clone.querySelectorAll('input,textarea,select').forEach(x=>{x.value=''});button.parentElement.insertBefore(clone,button)}
function moveListValue(button,direction){const row=button.parentElement,peer=direction<0?row.previousElementSibling:row.nextElementSibling;if(!peer)return;if(direction<0)row.parentElement.insertBefore(row,peer);else row.parentElement.insertBefore(peer,row)}
function readFields(props,form){const out={};for(const p of props){if(p.cardinality==='many')out[p.name]=[...form.querySelectorAll(`[name="prop_${p.name}"]`)].map(x=>coerce(p,x.value)).filter(x=>x!=='');else{const x=form.querySelector(`[name="prop_${p.name}"]`);if(x&&x.value!=='')out[p.name]=coerce(p,x.value)}}return out}function coerce(p,v){if(p.value_kind==='number')return Number(v);if(p.value_kind==='boolean')return v==='true';if(p.value_kind==='json'){try{return JSON.parse(v)}catch{return v}}return v}
function showRelationshipForm(){const types=state.types.filter(t=>t.kind==='relationship');if(!types.length)return showTypeForm('relationship');if(state.entities.length<2)return showEntityForm();const type=types[0],props=type.schema?.properties||[];formShell('Create a relationship',`<form id="relationship-form"><div class="field"><label>Relationship type</label><select name="typeId">${types.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="form-row"><div class="field"><label>From</label><select name="fromEntityId">${state.entities.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>To</label><select name="toEntityId">${state.entities.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></div></div>${props.map(p=>fieldFor(p)).join('')}<button class="button">Create relationship</button></form>`);$('#relationship-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),d={typeId:f.get('typeId'),fromEntityId:f.get('fromEntityId'),toEntityId:f.get('toEntityId'),data:readFields(props,e.target)};try{await api('/api/relationships',{method:'POST',body:JSON.stringify(d)});await load();showSection('relationships');toast('Relationship created')}catch(err){toast(err.message)}}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>showSection(b.dataset.section));load().catch(err=>toast(err.message));

// Relationship type authoring is intentionally available from the relationship workspace,
// alongside instance creation, so semantic definitions are discoverable in the main workflow.
function showTypeForm(kind='entity',existing){const t=existing||null;const entityKinds=state.types.filter(x=>x.kind==='entity').map(x=>x.name);const config=t?.schema?.config||{};const configFields=kind==='view'?`<div class="section-title"><h2>View projection</h2></div><div class="form-row"><div class="field"><label>Source kind</label><select name="source_kind"><option value="entity" ${config.source_kind!=='relationship'?'selected':''}>Entity</option><option value="relationship" ${config.source_kind==='relationship'?'selected':''}>Relationship</option></select></div><div class="field"><label>Layout</label><select name="layout"><option ${config.layout==='list'?'selected':''}>list</option><option ${config.layout==='table'?'selected':''}>table</option><option ${config.layout==='graph'?'selected':''}>graph</option><option ${config.layout==='timeline'?'selected':''}>timeline</option></select></div></div><div class="field"><label>Filter expression</label><input name="filter" value="${esc(config.filter)}" placeholder="Optional filter"></div>`:kind==='presentation'?`<div class="section-title"><h2>Presentation composition</h2></div><div class="field"><label>Ordered view IDs (one per line)</label><textarea name="view_ids">${esc((config.view_ids||[]).join('\n'))}</textarea></div><div class="field"><label>Active view ID</label><input name="active_view_id" value="${esc(config.active_view_id)}"></div>`:'';formShell(`${t?'Edit':'Define'} a ${kind} type`,`<form id="type-form"><div class="form-row"><div class="field"><label>Kind</label><select name="kind" ${t?'disabled':''}>${['entity','relationship','view','presentation'].map(k=>`<option ${k===kind?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label>Name</label><input name="name" value="${esc(t?.name)}" placeholder="e.g. Character" required></div></div><div class="field"><label>Description</label><textarea name="description" placeholder="What does this definition represent?">${esc(t?.description)}</textarea></div>${kind==='relationship'?`<div class="form-row"><div class="field"><label>Directionality</label><select name="directionality"><option value="directed" ${t?.schema?.directionality!=='undirected'?'selected':''}>Directed</option><option value="undirected" ${t?.schema?.directionality==='undirected'?'selected':''}>Undirected</option></select></div><div class="field"><label>Inverse label (optional)</label><input name="inverse_label" value="${esc(t?.schema?.inverse_label)}" placeholder="e.g. is owned by"></div></div><div class="form-row"><div class="field"><label>Allowed source entity types</label><select name="source_kinds" multiple>${entityKinds.map(k=>`<option ${t?.schema?.source_kinds?.includes(k)?'selected':''}>${esc(k)}</option>`).join('')}</select></div><div class="field"><label>Allowed target entity types</label><select name="target_kinds" multiple>${entityKinds.map(k=>`<option ${t?.schema?.target_kinds?.includes(k)?'selected':''}>${esc(k)}</option>`).join('')}</select></div></div>`:''}${configFields}<div class="section-title"><h2>Properties</h2><button type="button" class="button secondary small" id="add-property">+ Add property</button></div><div id="properties">${(t?.schema?.properties||[]).map(propertyRow).join('')}</div><button class="button">Save definition</button></form>`);document.querySelector('#add-property').onclick=()=>document.querySelector('#properties').insertAdjacentHTML('beforeend',propertyRow({},document.querySelectorAll('.property-row').length));document.querySelector('#type-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body={kind,name:f.get('name'),description:f.get('description'),schema:{directionality:f.get('directionality')||'directed',properties:collectProperties(),source_kinds:[...e.target.querySelector('[name="source_kinds"]')?.selectedOptions||[]].map(x=>x.value),target_kinds:[...e.target.querySelector('[name="target_kinds"]')?.selectedOptions||[]].map(x=>x.value),inverse_label:f.get('inverse_label')||'',config:{source_kind:f.get('source_kind')||'',layout:f.get('layout')||'',filter:f.get('filter')||'',view_ids:(f.get('view_ids')||'').split('\n').map(x=>x.trim()).filter(Boolean),active_view_id:f.get('active_view_id')||''}}};try{await api(t?`/api/types/${t.id}`:'/api/types',{method:t?'PUT':'POST',body:JSON.stringify(body)});await load();showSection(kindLabel(kind).toLowerCase());toast('Definition saved')}catch(err){toast(err.message)}}}
function renderRelationships(){const typeFilter=state.relationshipFilter;const rows=state.relationships.filter(r=>!typeFilter||r.type_id===typeFilter);$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">RELATIONSHIP RECORDS</div><h1>Relationships</h1><p>Connections are typed facts with constrained endpoints and their own properties.</p></div><div><button class="button secondary" onclick="showTypeForm('relationship')">+ Define relationship type</button> <button class="button" onclick="showRelationshipForm()">+ New relationship</button></div></div>${typeFilter?`<p class="muted">Showing <strong>${esc(state.types.find(t=>t.id===typeFilter)?.name||'selected type')}</strong> · <button class="button secondary small" onclick="state.relationshipFilter='';renderRelationships()">Show all</button></p>`:''}<div class="card">${rows.length?`<table class="table"><thead><tr><th>Type</th><th>From</th><th>To</th><th>Properties</th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="chip">${esc(r.type_name)}</span></td><td>${esc(r.from_name)}</td><td>${esc(r.to_name)}</td><td>${renderDataSummary(r.data)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No relationships yet. Define a type and create a connection.</div>'}</div>`}
function endpointOptions(kindNames,selected=''){return state.entities.filter(e=>!kindNames?.length||kindNames.includes(e.type_name)).map(e=>`<option value="${e.id}" ${e.id===selected?'selected':''}>${esc(e.name)} · ${esc(e.type_name)}</option>`).join('')}
function showRelationshipForm(id){const existing=id&&state.relationships.find(r=>r.id===id),types=state.types.filter(t=>t.kind==='relationship');if(!types.length)return showTypeForm('relationship');const initial=existing?types.find(t=>t.id===existing.type_id)||types[0]:types[0];const drafts={};formShell(`${existing?'Edit':'Create'} a relationship`,`<form id="relationship-form"><div class="field"><label>Relationship type</label><select name="typeId" ${existing?'disabled':''}>${types.map(t=>`<option value="${t.id}" ${t.id===initial.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select><small class="muted">Endpoint choices are limited by the selected relationship type.</small></div><div class="form-row"><div class="field"><label>From</label><select name="fromEntityId"></select></div><div class="field"><label>To</label><select name="toEntityId"></select></div></div><div id="relationship-fields"></div><button class="button">${existing?'Save changes':'Create relationship'}</button></form>`);const form=$('#relationship-form'),typeSelect=form.querySelector('[name="typeId"]'),from=form.querySelector('[name="fromEntityId"]'),to=form.querySelector('[name="toEntityId"]'),fields=form.querySelector('#relationship-fields');const renderSelected=(capture=true)=>{const type=types.find(t=>t.id===typeSelect.value)||initial,props=type.schema?.properties||[],draft=drafts[type.id]||{};if(capture&&fields.innerHTML)drafts[type.id]=readFields(props,form);const currentFrom=from.value||existing?.from_entity_id||'',currentTo=to.value||existing?.to_entity_id||'';from.innerHTML=endpointOptions(type.schema?.source_kinds,currentFrom);to.innerHTML=endpointOptions(type.schema?.target_kinds,currentTo);fields.innerHTML=props.map(p=>fieldFor(p,draft[p.name]??(existing?.data||{})[p.name])).join('');};typeSelect.onchange=()=>renderSelected();renderSelected(false);form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),type=types.find(t=>t.id===f.get('typeId'))||initial,props=type.schema?.properties||[];try{await api(existing?`/api/relationships/${existing.id}`:'/api/relationships',{method:existing?'PUT':'POST',body:JSON.stringify({typeId:type.id,fromEntityId:f.get('fromEntityId'),toEntityId:f.get('toEntityId'),data:readFields(props,form)})});await load();showSection('relationships');toast(existing?'Relationship updated':'Relationship created')}catch(err){toast(err.message)}}}
function renderRelationships(){const typeFilter=state.relationshipFilter;const rows=state.relationships.filter(r=>!typeFilter||r.type_id===typeFilter);$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">RELATIONSHIP RECORDS</div><h1>Relationships</h1><p>Connections are typed facts with constrained endpoints and their own properties.</p></div><div><button class="button secondary" onclick="showTypeForm('relationship')">+ Define relationship type</button> <button class="button" onclick="showRelationshipForm()">+ New relationship</button></div></div>${typeFilter?`<p class="muted">Showing <strong>${esc(state.types.find(t=>t.id===typeFilter)?.name||'selected type')}</strong> · <button class="button secondary small" onclick="state.relationshipFilter='';renderRelationships()">Show all</button></p>`:''}<div class="card">${rows.length?`<table class="table"><thead><tr><th>Type</th><th>From</th><th>To</th><th>Properties</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><span class="chip">${esc(r.type_name)}</span></td><td>${esc(r.from_name)}</td><td>${esc(r.to_name)}</td><td>${renderDataSummary(r.data)}</td><td><button class="button secondary small" onclick="showRelationshipForm('${r.id}')">Edit</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No relationships yet. Define a type and create a connection.</div>'}</div>`}

const GRAPH_DENSITY_LIMITS=Object.freeze({nodes:250,edges:500});
const graphText=value=>{const text=String(value??'');return text.length>160?`${text.slice(0,159)}…`:text};
const graphRecord=(kind,id)=>kind==='node'?(state.graph?.nodes||[]).find(item=>item.id===id):(state.graph?.edges||[]).find(item=>item.id===id);
function selectGraphItem(kind,id){if(!graphRecord(kind,id))return;state.graphSelection={kind,id};state.graphInspector=false;renderGraph()}
function inspectGraphItem(kind,id){if(!graphRecord(kind,id))return;state.graphSelection={kind,id};state.graphInspector=true;renderGraph()}
function openGraphSource(kind,id){const item=graphRecord(kind,id);if(!item)return;showSection(kind==='node'?'entities':'relationships',item.type_id)}
const graphItemActions=(kind,id)=>`<div class="graph-actions"><button type="button" class="button secondary small" data-graph-action="select" onclick="selectGraphItem('${kind}','${id}');event.stopPropagation()">Select</button><button type="button" class="button secondary small" data-graph-action="inspect" onclick="inspectGraphItem('${kind}','${id}');event.stopPropagation()">Inspect</button><button type="button" class="button secondary small" data-graph-action="source-open" onclick="openGraphSource('${kind}','${id}');event.stopPropagation()">Open source</button></div>`;
function graphInspectorMarkup(){
  const selection=state.graphSelection,item=selection&&graphRecord(selection.kind,selection.id);
  if(!state.graphInspector||!item)return '<section class="graph-inspector" aria-live="polite"><h3>Selection</h3><p class="muted">Select or inspect a graph item to review its source fact.</p></section>';
  const source=selection.kind==='edge'?(state.graph?.nodes||[]).find(node=>node.id===item.source):null;
  const target=selection.kind==='edge'?(state.graph?.nodes||[]).find(node=>node.id===item.target):null;
  const label=selection.kind==='node'?(item.label||item.name):item.type_name;
  const details=selection.kind==='node'?`<dt>Type</dt><dd>${esc(graphText(item.type_name))}</dd><dt>Label</dt><dd>${esc(graphText(label))}</dd>`:`<dt>From</dt><dd>${esc(graphText(source?.label||source?.name||'Unknown'))}</dd><dt>To</dt><dd>${esc(graphText(target?.label||target?.name||'Unknown'))}</dd><dt>Direction</dt><dd>${esc(graphText(item.directionality))}</dd>`;
  return `<section class="graph-inspector" aria-live="polite" aria-atomic="true"><h3>Inspecting ${esc(graphText(label))}</h3><dl>${details}</dl><small class="muted">Source ref ${esc(graphText(item.id).slice(0,12))}…</small><div class="graph-actions"><button type="button" class="button secondary small" data-graph-action="source-open" onclick="openGraphSource('${selection.kind}','${item.id}')">Open source</button></div></section>`;
}

function renderGraph(){
  const activeElement=document.activeElement;
  const activeSurface=activeElement?.closest?.('.structured-panel')?'structured':'visual';
  const focusKey=activeElement?.dataset?.graphEntity?`filter-entity:${activeElement.dataset.graphEntity}`:activeElement?.dataset?.graphRelationship?`filter-relationship:${activeElement.dataset.graphRelationship}`:activeElement?.dataset?.graphNode?`${activeSurface}-node:${activeElement.dataset.graphNode}`:activeElement?.dataset?.graphEdge?`${activeSurface}-edge:${activeElement.dataset.graphEdge}`:'';
  const entityTypes=state.types.filter(t=>t.kind==='entity'),relationshipTypes=state.types.filter(t=>t.kind==='relationship');
  const graphNodes=state.graph?.nodes||state.entities;
  const graphEdges=state.graph?.edges||state.relationships.map(r=>({...r,source:r.from_entity_id,target:r.to_entity_id}));
  const selectedEntities=new Set(state.graphEntityFilters||entityTypes.map(t=>t.id)),selectedRelationships=new Set(state.graphRelationshipFilters||relationshipTypes.map(t=>t.id));
  const visibleNodes=graphNodes.filter(e=>selectedEntities.has(e.type_id));
  const visibleNodeIds=new Set(visibleNodes.map(e=>e.id));
  const visibleEdges=graphEdges.filter(r=>selectedRelationships.has(r.type_id)&&visibleNodeIds.has(r.source)&&visibleNodeIds.has(r.target));
  const hiddenEdges=graphEdges.filter(r=>selectedRelationships.has(r.type_id)&&(!visibleNodeIds.has(r.source)||!visibleNodeIds.has(r.target))).length;
  const eligibleNodeCount=state.graph?.density?.eligible_nodes??state.graph?.counts?.eligible_nodes??graphNodes.length;
  const eligibleEdgeCount=state.graph?.density?.eligible_edges??state.graph?.counts?.eligible_edges??graphEdges.length;
  const denseInput=state.graph?.density?.within_bounds===false||eligibleNodeCount>GRAPH_DENSITY_LIMITS.nodes||eligibleEdgeCount>GRAPH_DENSITY_LIMITS.edges;
  const nodeTypeOptions=entityTypes.map(t=>`<label class="filter-option"><input type="checkbox" data-graph-entity="${t.id}" ${selectedEntities.has(t.id)?'checked':''}>${esc(graphText(t.name))}</label>`).join('')||'<span class="muted">No entity types</span>';
  const relationshipTypeOptions=relationshipTypes.map(t=>`<label class="filter-option"><input type="checkbox" data-graph-relationship="${t.id}" ${selectedRelationships.has(t.id)?'checked':''}>${esc(graphText(t.name))}</label>`).join('')||'<span class="muted">No relationship types</span>';
  const positions=denseInput?new Map():new Map(visibleNodes.map((e,i)=>{const angle=(i/Math.max(visibleNodes.length,1))*Math.PI*2;return [e.id,{x:50+40*Math.cos(angle),y:50+36*Math.sin(angle)}]}));
  const svg=`<svg class="graph-canvas" viewBox="0 0 100 100" role="img" aria-label="Relationship graph with ${visibleNodes.length} nodes and ${visibleEdges.length} edges">${visibleEdges.map(r=>{const a=positions.get(r.source),b=positions.get(r.target),source=graphNodes.find(n=>n.id===r.source),target=graphNodes.find(n=>n.id===r.target),sourceLabel=source?.label||source?.name||'Unknown',targetLabel=target?.label||target?.name||'Unknown';return a&&b?`<g class="graph-edge-control" tabindex="0" role="img" aria-label="${esc(r.type_name)}: ${esc(sourceLabel)} ${r.directionality==='directed'?'to':'neutral to'} ${esc(targetLabel)}" data-graph-edge="${r.id}"><line class="graph-edge" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/><text class="graph-edge-label" x="${(a.x+b.x)/2}" y="${(a.y+b.y)/2}">${esc(r.type_name)}</text></g>`:''}).join('')}${visibleNodes.map(e=>{const p=positions.get(e.id),label=e.label||e.name;return `<g class="graph-node" tabindex="0" aria-label="${esc(label)} · ${esc(e.type_name)}" data-graph-node="${e.id}"><circle cx="${p.x}" cy="${p.y}" r="4"/><text x="${p.x}" y="${p.y-6}">${esc(label)}</text><title>${esc(label)} · ${esc(e.type_name)}</title></g>`}).join('')}</svg>`;
  const warningLabels={
    'density-limit':'Density limit: narrow filters before visual exploration.',
    'unknown-direction':'Unknown direction: shown as a neutral edge.',
    'missing-endpoint':'Missing endpoint: relationship omitted.',
    'malformed-edge':'Malformed relationship: row omitted.',
    'malformed-node':'Malformed entity: row omitted.',
    'duplicate-edge-id':'Duplicate relationship identity: row omitted.',
    'duplicate-node-id':'Duplicate entity identity: row omitted.',
    'missing-node-name':'Missing entity name: bounded placeholder used.',
    'unknown-entity-filter':'Entity filter is stale and was ignored.',
    'unknown-relationship-filter':'Relationship filter is stale and was ignored.',
    'bounded-label':'Display label was truncated to the bounded graph output length.'
  };
  const warningItems=(state.graph?.warnings||[]).map(w=>`<li><code>${esc(w.code)}</code> ${esc(warningLabels[w.code]||'Data-quality warning.')}</li>`).join('');
  const warningPanel=`<h3>Warnings</h3><ul class="graph-list graph-warnings">${warningItems||'<li class="muted">No data-quality warnings.</li>'}</ul>`;
  const visibleEdgeItems=visibleEdges.map(r=>{const source=graphNodes.find(n=>n.id===r.source),target=graphNodes.find(n=>n.id===r.target),sourceLabel=source?.label||source?.name||'Unknown',targetLabel=target?.label||target?.name||'Unknown';return `<li tabindex="0" data-graph-edge="${r.id}" aria-label="${esc(r.type_name)}: ${esc(sourceLabel)} ${r.directionality==='directed'?'to':'neutral to'} ${esc(targetLabel)}"><strong>${esc(r.type_name)}</strong>: ${esc(sourceLabel)} ${r.directionality==='directed'?'→':'—'} ${esc(targetLabel)}${r.directionality==='unknown'?' <span class="chip">direction unknown</span>':''}${graphItemActions('edge',r.id)}</li>`}).join('');
  const densityNotice=denseInput?` · density envelope exceeded (${eligibleNodeCount}/${GRAPH_DENSITY_LIMITS.nodes} nodes, ${eligibleEdgeCount}/${GRAPH_DENSITY_LIMITS.edges} edges)`:'';
  $('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">RELATIONSHIP EXPLORER</div><h1>Graph View</h1><p>Explore persisted Entity and Relationship facts. Views and Presentations remain separate definitions and are not graph facts.</p></div><button class="button secondary" onclick="showSection('overview')">Back to Overview</button></div><div class="graph-toolbar"><div><strong>Entities</strong><div class="filter-options">${nodeTypeOptions}</div></div><div><strong>Relationships</strong><div class="filter-options">${relationshipTypeOptions}</div></div><button class="button secondary small" id="graph-reset">Reset filters</button></div><div class="graph-summary" role="status"><strong>${visibleNodes.length}</strong> of ${state.graph?.counts?.eligible_nodes??graphNodes.length} entity nodes · <strong>${visibleEdges.length}</strong> of ${state.graph?.counts?.eligible_edges??graphEdges.length} relationship edges${hiddenEdges?` · ${hiddenEdges} edge${hiddenEdges===1?'':'s'} hidden by endpoint filters`:''}${state.graph?.warnings?.length?` · ${state.graph.warnings.length} warnings`:''}${densityNotice} · revision ${esc(state.graph?.revision||'local')}</div><div class="graph-layout"><div class="card graph-panel">${visibleNodes.length?svg:'<div class="empty">No eligible nodes match the selected filters.</div>'}</div><div class="card structured-panel"><h2>Structured graph data</h2><p class="muted">Keyboard-operable parity view for the same filtered facts.</p>${visibleNodes.length?`<ul class="graph-list">${visibleNodes.map(e=>`<li tabindex="0" data-graph-node="${e.id}" aria-label="${esc(e.label||e.name)} · ${esc(e.type_name)}"><strong>${esc(e.label||e.name)}</strong> <span class="chip">${esc(e.type_name)}</span><small>${visibleEdges.filter(r=>r.source===e.id||r.target===e.id).length} connected edges</small></li>`).join('')}</ul><h3>Relationships</h3><ul class="graph-list">${visibleEdgeItems||'<li class="muted">No visible relationships.</li>'}</ul>`:'<div class="empty">No nodes to list.</div>'}${warningPanel}</div></div>`;
  const graphSummary=document.querySelector('.graph-summary');
  graphSummary?.setAttribute('aria-live','polite');
  graphSummary?.setAttribute('aria-atomic','true');
  const graphPanel=document.querySelector('.graph-panel');
  if(denseInput&&graphPanel)graphPanel.innerHTML='<div class="empty graph-density-fallback" role="status" aria-live="polite">Visual layout disabled above the provisional density envelope; use structured graph data below.</div>';
  if(!visibleNodes.length&&graphPanel){graphPanel.setAttribute('role','status');graphPanel.setAttribute('aria-live','polite');graphPanel.setAttribute('aria-atomic','true')}
  const structuredPanel=document.querySelector('.structured-panel');
  structuredPanel?.setAttribute('aria-live','polite');
  structuredPanel?.setAttribute('aria-atomic','true');
  structuredPanel?.querySelectorAll('.empty').forEach(empty=>{empty.setAttribute('role','status');empty.setAttribute('aria-live','polite');empty.setAttribute('aria-atomic','true')});
  document.querySelectorAll('.structured-panel [data-graph-node]').forEach(item=>item.insertAdjacentHTML('beforeend',graphItemActions('node',item.dataset.graphNode)));
  document.querySelectorAll('.structured-panel [data-graph-edge]').forEach(item=>item.insertAdjacentHTML('beforeend',graphItemActions('edge',item.dataset.graphEdge)));
  document.querySelector('.structured-panel')?.insertAdjacentHTML('beforeend',graphInspectorMarkup());
  document.querySelectorAll('[data-graph-entity]').forEach(input=>input.onchange=()=>{state.graphEntityFilters=[...document.querySelectorAll('[data-graph-entity]:checked')].map(x=>x.dataset.graphEntity);renderGraph()});
  document.querySelectorAll('[data-graph-relationship]').forEach(input=>input.onchange=()=>{state.graphRelationshipFilters=[...document.querySelectorAll('[data-graph-relationship]:checked')].map(x=>x.dataset.graphRelationship);renderGraph()});
  $('#graph-reset').onclick=()=>{state.graphEntityFilters=entityTypes.map(t=>t.id);state.graphRelationshipFilters=relationshipTypes.map(t=>t.id);renderGraph()};
  if(focusKey){const [kind,id]=focusKey.split(':');let target;if(kind==='filter-entity')target=document.querySelector(`[data-graph-entity="${id}"]`);else if(kind==='filter-relationship')target=document.querySelector(`[data-graph-relationship="${id}"]`);else if(kind==='structured-node')target=document.querySelector(`.structured-panel [data-graph-node="${id}"]`);else if(kind==='structured-edge')target=document.querySelector(`.structured-panel [data-graph-edge="${id}"]`);else if(kind==='visual-node')target=document.querySelector(`.graph-panel [data-graph-node="${id}"]`);else if(kind==='visual-edge')target=document.querySelector(`.graph-panel [data-graph-edge="${id}"]`);target?.focus()}
}
function navState(){try{return JSON.parse(localStorage.getItem('facts-nav-expanded')||'{}')}catch{return {}}}
function renderNavigation(){const nav=$('#model-nav');if(!nav)return;const expanded=navState();const groups=[
  {key:'entities',label:'Entities',icon:'◆',count:state.entities.length,items:state.types.filter(t=>t.kind==='entity').map(t=>({id:t.id,name:t.name,count:state.entities.filter(e=>e.type_id===t.id).length}))},
  {key:'relationships',label:'Relationships',icon:'↔',count:state.relationships.length,items:state.types.filter(t=>t.kind==='relationship').map(t=>({id:t.id,name:t.name,count:state.relationships.filter(r=>r.type_id===t.id).length}))},
  {key:'views',label:'Views',icon:'▦',count:state.types.filter(t=>t.kind==='view').length,items:state.types.filter(t=>t.kind==='view').map(t=>({id:t.id,name:t.name}))},
  {key:'presentations',label:'Presentations',icon:'▤',count:state.types.filter(t=>t.kind==='presentation').length,items:state.types.filter(t=>t.kind==='presentation').map(t=>({id:t.id,name:t.name}))}
];nav.innerHTML=`<button class="nav-item ${state.activeSection==='overview'?'active':''}" data-section="overview" aria-label="Overview">⌂ <span>Overview</span></button><button class="nav-item ${state.activeSection==='graph'?'active':''}" data-section="graph" aria-label="Graph View">✦ <span>Graph View</span></button>${groups.map(g=>{const open=expanded[g.key]!==false;return `<div class="nav-group"><button class="nav-item nav-parent ${state.activeSection===g.key?'active':''}" data-nav-group="${g.key}" aria-expanded="${open}">${g.icon} <span>${g.label}</span><b>${g.count}</b></button><div class="nav-children" ${open?'':'hidden'}>${g.items.length?g.items.map(i=>`<button class="nav-item nav-child ${state.activeTypeId===i.id?'active':''}" data-section="${g.key}" data-type-id="${i.id}" title="Open ${esc(i.name)}"><span>${esc(i.name)}</span>${i.count==null?'':`<b>${i.count}</b>`}</button>`).join(''):`<div class="nav-empty">No ${g.label.toLowerCase()} yet · use + Define</div>`}</div></div>`}).join('')}`;nav.querySelector('[data-section="overview"]').onclick=()=>showSection('overview');nav.querySelector('[data-section="graph"]').onclick=()=>showSection('graph');nav.querySelectorAll('.nav-parent').forEach(b=>b.onclick=()=>{const key=b.dataset.navGroup, next={...navState(),[key]:b.getAttribute('aria-expanded')!=='true'};localStorage.setItem('facts-nav-expanded',JSON.stringify(next));renderNavigation()});nav.querySelectorAll('.nav-child').forEach(b=>b.onclick=()=>showSection(b.dataset.section,b.dataset.typeId))}
function showSection(s,typeId){state.activeSection=s;state.activeTypeId=typeId||'';if(s==='overview')return renderOverview();if(s==='graph')return renderGraph();if(s==='entities')return renderEntities(typeId);if(s==='relationships'){state.relationshipFilter=typeId||'';return renderRelationships()}return renderDefinitions(s,typeId)}
function renderEntities(typeId=state.activeTypeId){const filter=typeId||state.entityFilter||'';state.entityFilter=filter;const rows=state.entities.filter(e=>!filter||e.type_id===filter);renderNavigation();$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">ENTITY RECORDS</div><h1>Entities</h1><p>Create instances from typed definitions. Existing records can be edited and inspected field by field.</p></div><button class="button" onclick="showEntityForm()">+ New entity</button></div>${filter?`<p class="muted">Showing <strong>${esc(state.types.find(t=>t.id===filter)?.name||'selected type')}</strong> · <button class="button secondary small" onclick="showSection('entities','')">Show all</button></p>`:''}<div class="card">${rows.length?`<table class="table"><thead><tr><th>Name</th><th>Type</th><th>Properties</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.name)}</td><td><span class="chip">${esc(e.type_name)}</span></td><td>${renderDataSummary(e.data)}</td><td><button class="button secondary small" onclick="showEntityForm('${e.id}')">Edit</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No entity records yet. Define a type, then create your first instance.</div>'}</div>`}
function renderDefinitions(s,typeId=state.activeTypeId){const kind=s==='views'?'view':'presentation',filter=typeId||'';state.activeTypeId=filter;const items=state.types.filter(t=>t.kind===kind&&(!filter||t.id===filter));renderNavigation();$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">${kind.toUpperCase()} DEFINITIONS</div><h1>${kind[0].toUpperCase()+kind.slice(1)}s</h1><p>Definitions are stored as metadata and can be expanded as the model evolves.</p></div><button class="button" onclick="showTypeForm('${kind}')">+ Define ${kind}</button></div><div class="card-grid">${items.map(typeCard).join('')||'<div class="empty">No definitions yet. Use the button above to create the first one.</div>'}</div>`}
function renderOverview(){state.activeSection='overview';state.activeTypeId='';renderNavigation();$('#content').innerHTML=`<div class="hero"><div><div class="eyebrow">COMPOSABLE META-MODEL WORKSPACE · ${esc(state.version||'')}</div><h1>Give your domain a shape.</h1><p>Define forms first, then instantiate the people, places, objects, and events your work needs.</p></div><div><button class="button" onclick="showTypeForm('entity')">+ Define an entity type</button><button class="button secondary small" onclick="resetWorkspace()">Reset test workspace</button></div></div><div class="grid"><div class="stat"><div class="stat-label">Entity types</div><div class="stat-value">${state.types.filter(t=>t.kind==='entity').length}</div></div><div class="stat"><div class="stat-label">Entity records</div><div class="stat-value">${state.entities.length}</div></div><div class="stat"><div class="stat-label">Relationships</div><div class="stat-value">${state.relationships.length}</div></div><div class="stat"><div class="stat-label">View definitions</div><div class="stat-value">${state.types.filter(t=>['view','presentation'].includes(t.kind)).length}</div></div></div><div class="section-title"><h2>Definitions</h2><span class="chip">Metadata-driven</span></div><div class="card-grid">${state.types.map(typeCard).join('')}</div>`}
async function load(){const health=await api('/api/health');state.version=health.version;state.runId=health.run_id;[state.types,state.entities,state.relationships,state.graph]=await Promise.all([api('/api/types'),api('/api/entities'),api('/api/relationships'),api('/api/graph')]);const run=$('#run-id');if(run)run.textContent=esc(state.runId);state.activeSection=state.activeSection||'overview';renderNavigation();if(state.activeSection==='overview')renderOverview();else showSection(state.activeSection,state.activeTypeId)}

let presentationDraft={order:[],active:''};
function renderPresentationOrder(){const list=$('#presentation-order'),active=$('#presentation-active');if(!list||!active)return;const views=state.types.filter(t=>t.kind==='view'),byId=new Map(views.map(v=>[v.id,v]));presentationDraft.order=presentationDraft.order.filter(id=>byId.has(id));if(presentationDraft.active&&!presentationDraft.order.includes(presentationDraft.active))presentationDraft.active=presentationDraft.order[0]||'';list.innerHTML=presentationDraft.order.length?presentationDraft.order.map((id,index)=>`<div class="list-value ordered-view"><span>${index+1}. ${esc(byId.get(id)?.name||'Unavailable view')}</span><button type="button" class="button secondary small" onclick="movePresentationView(${index},-1)">↑</button><button type="button" class="button secondary small" onclick="movePresentationView(${index},1)">↓</button><button type="button" class="button secondary small" onclick="removePresentationView('${id}')">−</button></div>`).join(''):'<div class="empty">No views selected. Add a saved view above.</div>';active.innerHTML=`<option value="">— Choose active view —</option>${presentationDraft.order.map(id=>`<option value="${id}" ${id===presentationDraft.active?'selected':''}>${esc(byId.get(id)?.name||'Unavailable view')}</option>`).join('')}`;}
function addPresentationView(){const select=$('#presentation-add'),id=select?.value;if(!id||presentationDraft.order.includes(id))return;presentationDraft.order.push(id);if(!presentationDraft.active)presentationDraft.active=id;renderPresentationOrder()}
function movePresentationView(index,direction){const next=index+direction;if(next<0||next>=presentationDraft.order.length)return;[presentationDraft.order[index],presentationDraft.order[next]]=[presentationDraft.order[next],presentationDraft.order[index]];renderPresentationOrder()}
function removePresentationView(id){presentationDraft.order=presentationDraft.order.filter(x=>x!==id);if(presentationDraft.active===id)presentationDraft.active=presentationDraft.order[0]||'';renderPresentationOrder()}
function showTypeForm(kind='entity',existing){const t=existing||null,entityKinds=state.types.filter(x=>x.kind==='entity').map(x=>x.name),config=t?.schema?.config||{};if(kind==='presentation'){presentationDraft={order:Array.isArray(config.view_ids)?[...config.view_ids]:[],active:config.active_view_id||''};}const configFields=kind==='view'?`<div class="section-title"><h2>View projection</h2></div><div class="form-row"><div class="field"><label>Source kind</label><select name="source_kind"><option value="entity" ${config.source_kind!=='relationship'?'selected':''}>Entity</option><option value="relationship" ${config.source_kind==='relationship'?'selected':''}>Relationship</option></select></div><div class="field"><label>Layout</label><select name="layout"><option value="list" ${config.layout==='list'?'selected':''}>list</option><option value="table" ${config.layout==='table'?'selected':''}>table</option><option value="graph" ${config.layout==='graph'?'selected':''}>graph</option><option value="timeline" ${config.layout==='timeline'?'selected':''}>timeline</option></select></div></div><div class="field"><label>Filter expression</label><input name="filter" value="${esc(config.filter)}" placeholder="Optional filter"></div>`:kind==='presentation'?`<div class="section-title"><h2>Presentation composition</h2></div><div class="field"><label>Add a saved view</label><div class="form-row"><select id="presentation-add"><option value="">— Select view —</option>${state.types.filter(x=>x.kind==='view').map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select><button type="button" class="button secondary" onclick="addPresentationView()">Add view</button></div></div><div class="field"><label>Ordered views</label><div id="presentation-order"></div></div><div class="field"><label>Active view</label><select id="presentation-active" name="active_view_id"></select><small class="muted">Only selected, available views can be active. Missing or deleted views are removed before save.</small></div>`:'';formShell(`${t?'Edit':'Define'} a ${kind} type`,`<form id="type-form"><div class="form-row"><div class="field"><label>Kind</label><select name="kind" disabled>${['entity','relationship','view','presentation'].map(k=>`<option ${k===kind?'selected':''}>${k}</option>`).join('')}</select></div><div class="field"><label>Name</label><input name="name" value="${esc(t?.name)}" placeholder="e.g. Character dossier" required></div></div><div class="field"><label>Description</label><textarea name="description" placeholder="What does this definition represent?">${esc(t?.description)}</textarea></div>${kind==='relationship'?`<div class="form-row"><div class="field"><label>Directionality</label><select name="directionality"><option value="directed" ${t?.schema?.directionality!=='undirected'?'selected':''}>Directed</option><option value="undirected" ${t?.schema?.directionality==='undirected'?'selected':''}>Undirected</option></select></div><div class="field"><label>Inverse label (optional)</label><input name="inverse_label" value="${esc(t?.schema?.inverse_label)}" placeholder="e.g. is owned by"></div></div><div class="form-row"><div class="field"><label>Allowed source entity types</label><select name="source_kinds" multiple>${entityKinds.map(k=>`<option ${t?.schema?.source_kinds?.includes(k)?'selected':''}>${esc(k)}</option>`).join('')}</select></div><div class="field"><label>Allowed target entity types</label><select name="target_kinds" multiple>${entityKinds.map(k=>`<option ${t?.schema?.target_kinds?.includes(k)?'selected':''}>${esc(k)}</option>`).join('')}</select></div></div>`:''}${configFields}<div class="section-title"><h2>Properties</h2><button type="button" class="button secondary small" id="add-property">+ Add property</button></div><div id="properties">${(t?.schema?.properties||[]).map(propertyRow).join('')}</div><button class="button">Save definition</button></form>`);if(kind==='presentation')renderPresentationOrder();$('#add-property').onclick=()=>$('#properties').insertAdjacentHTML('beforeend',propertyRow({},document.querySelectorAll('.property-row').length));$('#type-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),body={kind,name:f.get('name'),description:f.get('description'),schema:{directionality:f.get('directionality')||'directed',properties:collectProperties(),source_kinds:[...e.target.querySelector('[name="source_kinds"]')?.selectedOptions||[]].map(x=>x.value),target_kinds:[...e.target.querySelector('[name="target_kinds"]')?.selectedOptions||[]].map(x=>x.value),inverse_label:f.get('inverse_label')||'',config:{source_kind:f.get('source_kind')||'',layout:f.get('layout')||'',filter:f.get('filter')||'',view_ids:kind==='presentation'?[...presentationDraft.order]:[],active_view_id:kind==='presentation'?presentationDraft.active:f.get('active_view_id')||''}}};try{await api(t?`/api/types/${t.id}`:'/api/types',{method:t?'PUT':'POST',body:JSON.stringify(body)});await load();showSection(kindLabel(kind).toLowerCase());toast('Definition saved')}catch(err){toast(err.message)}}}
document.addEventListener('change',event=>{if(event.target.id==='presentation-active')presentationDraft.active=event.target.value;});
